plugins {
    alias(libs.plugins.kotlin.jvm)
    alias(libs.plugins.kotlin.serialization)
    alias(libs.plugins.spotless)
    alias(libs.plugins.versions)
    `java-library`
}

repositories {
    mavenCentral()
}

dependencies {
    api(libs.slf4j.api)
    implementation(libs.kotlinx.serialization.json)
    implementation(libs.clikt)
    implementation(libs.sqlite.jdbc)

    testImplementation(libs.junit.jupiter)
    testImplementation(libs.junit.jupiter.params)
    testRuntimeOnly(libs.slf4j.simple)
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

kotlin {
    jvmToolchain(21)
}

tasks.register<JavaExec>("generateDatasetManifest") {
    group = "application"
    description = "Generate dataset-manifest.json for IMDb TSV/GZ files."
    classpath = sourceSets["main"].runtimeClasspath
    mainClass = "com.kimdb.tsv.GenerateDatasetManifestKt"
    workingDir = rootProject.projectDir
}

tasks.register<JavaExec>("importImdbToSqlite") {
    group = "application"
    description = "Import IMDb TSV data into SQLite database."
    classpath = sourceSets["main"].runtimeClasspath
    mainClass = "com.kimdb.tsv.ImportImdbToSqliteKt"
    workingDir = rootProject.projectDir
}

tasks.register<JavaExec>("verifyImdbToSqlite") {
    group = "application"
    description = "Verify SQLite import row counts/indexes against IMDb TSV files."
    classpath = sourceSets["main"].runtimeClasspath
    mainClass = "com.kimdb.tsv.VerifyImdbToSqliteKt"
    workingDir = rootProject.projectDir
}

tasks.register<JavaExec>("benchmarkBackends") {
    group = "application"
    description = "Benchmark in-memory vs SQLite repository operations."
    classpath = sourceSets["main"].runtimeClasspath
    mainClass = "com.kimdb.bench.BenchmarkBackendsKt"
    workingDir = rootProject.projectDir
}

tasks.register<JavaExec>("verifyBackendsParity") {
    group = "verification"
    description = "Verify selected query parity between in-memory and SQLite repositories."
    classpath = sourceSets["main"].runtimeClasspath
    mainClass = "com.kimdb.bench.VerifyBackendsParityKt"
    workingDir = rootProject.projectDir
}

tasks.withType<Test>().configureEach {
    useJUnitPlatform()

    // Stable defaults for IMDb-scale integration tests:
    // - single fork avoids concurrent large in-memory datasets
    // - periodic fork limits long-lived heap growth
    maxParallelForks = 1
    forkEvery = 12
    minHeapSize = "1g"
    maxHeapSize = "16g"
}

spotless {
    kotlin {
        target("src/**/*.kt")
        ktlint().editorConfigOverride(
            mapOf(
                "ij_kotlin_allow_trailing_comma" to "false",
                "ij_kotlin_allow_trailing_comma_on_call_site" to "false"
            )
        )
    }
    kotlinGradle {
        target("*.gradle.kts")
        ktlint().editorConfigOverride(
            mapOf(
                "ij_kotlin_allow_trailing_comma" to "false",
                "ij_kotlin_allow_trailing_comma_on_call_site" to "false"
            )
        )
    }
}
